// src/components/student/DashboardStudent.js
import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Grid, 
  Paper, 
  Typography, 
  Card, 
  CardContent,
  Box,
  Chip,
  Alert
} from '@mui/material';
import {
  School as SchoolIcon,
  Assignment as AssignmentIcon,
  Grade as GradeIcon,
  BarChart as ChartIcon
} from '@mui/icons-material';
import StudentCourses from './StudentCourses';
import StudentGrades from './StudentGrades';
import StudentAssignments from './StudentAssignments';
import StudentStats from './StudentStats';
import { studentService } from '../../services/studentService';

const DashboardStudent = () => {
  const [studentData, setStudentData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('courses');

  useEffect(() => {
    fetchStudentData();
  }, []);

  const fetchStudentData = async () => {
    try {
      setLoading(true);
      const data = await studentService.getDashboardData();
      setStudentData(data);
    } catch (error) {
      console.error('Erreur chargement dashboard étudiant:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Container>
        <Typography>Chargement du dashboard...</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
      {/* En-tête Dashboard */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" gutterBottom>
          Dashboard Étudiant
        </Typography>
        {studentData && (
          <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap' }}>
            <Typography variant="h6" color="primary">
              {studentData.student.nom}
            </Typography>
            <Chip 
              label={`Classe: ${studentData.student.class_name || 'Non assignée'}`} 
              variant="outlined" 
            />
            <Chip 
              label={`${studentData.coursesCount} cours`} 
              color="primary" 
              size="small" 
            />
          </Box>
        )}
      </Box>

      {/* Cartes de statistiques rapides */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <SchoolIcon color="primary" />
                <Box>
                  <Typography variant="h4">
                    {studentData?.coursesCount || 0}
                  </Typography>
                  <Typography color="textSecondary">
                    Mes Cours
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <GradeIcon color="secondary" />
                <Box>
                  <Typography variant="h4">
                    {studentData?.gradesCount || 0}
                  </Typography>
                  <Typography color="textSecondary">
                    Notes
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <AssignmentIcon color="info" />
                <Box>
                  <Typography variant="h4">
                    {studentData?.assignmentsCount || 0}
                  </Typography>
                  <Typography color="textSecondary">
                    Devoirs
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <ChartIcon color="success" />
                <Box>
                  <Typography variant="h4">
                    {studentData?.averageGrade ? studentData.averageGrade.toFixed(1) : '0.0'}
                  </Typography>
                  <Typography color="textSecondary">
                    Moyenne
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Navigation par onglets */}
      <Paper sx={{ mb: 3 }}>
        <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Box sx={{ display: 'flex' }}>
            {[
              { id: 'courses', label: 'Mes Cours', icon: <SchoolIcon /> },
              { id: 'grades', label: 'Mes Notes', icon: <GradeIcon /> },
              { id: 'assignments', label: 'Devoirs', icon: <AssignmentIcon /> },
              { id: 'stats', label: 'Statistiques', icon: <ChartIcon /> }
            ].map((tab) => (
              <Box
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                sx={{
                  px: 3,
                  py: 2,
                  cursor: 'pointer',
                  borderBottom: activeTab === tab.id ? 2 : 0,
                  borderColor: 'primary.main',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 1,
                  color: activeTab === tab.id ? 'primary.main' : 'text.primary',
                  fontWeight: activeTab === tab.id ? 'bold' : 'normal'
                }}
              >
                {tab.icon}
                <Typography>{tab.label}</Typography>
              </Box>
            ))}
          </Box>
        </Box>
      </Paper>

      {/* Contenu des onglets */}
      <Box>
        {activeTab === 'courses' && <StudentCourses />}
        {activeTab === 'grades' && <StudentGrades />}
        {activeTab === 'assignments' && <StudentAssignments />}
        {activeTab === 'stats' && <StudentStats />}
      </Box>
    </Container>
  );
};

export default DashboardStudent;
